// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; !ok {
		return ErrNotFound
	}
	delete(s.members, k)
	return nil
}

args.new_string:
// SetMemberRole changes a member's role. An organization's only owner cannot be demoted: ErrLastOwner.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	if role != RoleOwner && s.isLastOwnerLocked(m) {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
// An organization's only owner cannot be removed: ErrLastOwner.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return ErrNotFound
	}
	if s.isLastOwnerLocked(m) {
		return ErrLastOwner
	}
	delete(s.members, k)
	return nil
}

// isLastOwnerLocked reports whether m is the only owner of its organization. The caller holds s.mu.
func (s *Store) isLastOwnerLocked(m Member) bool {
	if m.Role != RoleOwner {
		return false
	}
	owners := 0
	for _, o := range s.members {
		if o.OrgID == m.OrgID && o.Role == RoleOwner {
			owners++
		}
	}
	return owners == 1
}

