func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return ErrNotFound
	}
	if s.isLastOwnerLocked(m) {
		return ErrLastOwner
	}
	delete(s.members, k)
	return nil
}

